contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0);
        require(amount <= c.balanceOf(address(this)));

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        uint256 distributedBefore = c.totalDistributed();
        uint256 remainingBefore = c.totalRemaining();

        bool reverted;
        try c.burn(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted
                ? (c.balanceOf(address(this)) == balanceBefore - amount &&
                   c.totalSupply() == supplyBefore - amount &&
                   c.totalDistributed() == distributedBefore - amount &&
                   c.totalRemaining() == remainingBefore)
                : (c.balanceOf(address(this)) == balanceBefore &&
                   c.totalSupply() == supplyBefore &&
                   c.totalDistributed() == distributedBefore &&
                   c.totalRemaining() == remainingBefore)
        );
    }

    receive() external payable {}
}

